UPDATE song_masters SET track=NULL, disc=NULL, updated_at=unixepoch() WHERE id IN (SELECT master_id FROM expected) AND (SELECT COUNT(*) FROM song_masters sm JOIN expected e ON e.master_id=sm.id WHERE sm.album_id=e.target_album_id AND sm.track=e.filename_track AND sm.disc=1
AND EXISTS (SELECT 1 FROM song_instances si JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file'
            WHERE si.id=e.instance_id AND si.master_id=sm.id AND si.source_id=e.source_id
              AND si.storage_object_id=e.storage_object_id AND se.id=e.entry_id AND se.source_id=e.source_id
              AND se.parent_id=e.parent_id AND se.path=e.path AND se.display_name=e.display_name))=(SELECT COUNT(*) FROM expected);
